<?php
declare(strict_types=1);require '../includes/security.php';require_authentication();require '../database/db.php';
function e(string $value): string{return htmlspecialchars($value,ENT_QUOTES,'UTF-8');}
$user_id=(int)$_SESSION['user_id'];$csrf=e(csrf_token());$statement=$con->prepare('SELECT blog_id,title,created_at,image,description FROM blogs WHERE user_id=? ORDER BY created_at DESC');$statement->bind_param('i',$user_id);$statement->execute();$result=$statement->get_result();
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta name="description" content="Manage your published Weblogr stories."><title>My Posts | Weblogr</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="../assets/weblogr-product.css"><link rel="stylesheet" href="../assets/responsive.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include 'sidebar.php';?><main class="content"><div class="all-posts-container"><header class="feed-header"><p class="eyebrow">YOUR WRITING</p><h1>My Posts</h1><p>Manage your published stories and keep your profile fresh.</p></header><div class="page-header"><div><p class="section-title">Published stories</p><p><?php echo (int)$result->num_rows;?> <?php echo $result->num_rows===1?'story':'stories'; ?> published.</p></div><a href="new_post.php" class="submit"><i class="fas fa-pen-nib"></i> Write a story</a></div><?php if($result->num_rows>0):?><div class="posts-list"><?php while($row=$result->fetch_assoc()):?><article class="post-container"><div class="date-container"><span><i class="far fa-calendar"></i> <?php echo e(date('d M Y',strtotime((string)$row['created_at'])));?></span><span>Story #<?php echo(int)$row['blog_id'];?></span></div><h2 id="display-title"><?php echo e((string)$row['title']);?></h2><?php if(!empty($row['image'])):?><img id="display-image" src="../images/<?php echo rawurlencode((string)$row['image']);?>" alt="<?php echo e((string)$row['title']);?>" loading="lazy"><?php endif;?><p id="display-para"><?php echo nl2br(e((string)$row['description']));?></p><div class="post-actions"><a href="edit_post.php?blog_id=<?php echo(int)$row['blog_id'];?>" class="secondary-button"><i class="fas fa-pen"></i> Edit</a><a href="../blog.php?blog_id=<?php echo(int)$row['blog_id'];?>" class="secondary-button"><i class="fas fa-eye"></i> View</a><form action="delete_post.php" method="post" class="inline-delete-form" data-confirm="Delete this story? This action cannot be undone."><input type="hidden" name="blog_id" value="<?php echo(int)$row['blog_id'];?>"><input type="hidden" name="csrf_token" value="<?php echo $csrf;?>"><button type="submit" class="danger-button"><i class="fas fa-trash-alt"></i> Delete</button></form></div></article><?php endwhile;?></div><?php else:?><div class="empty-state"><div class="empty-icon"><i class="fas fa-pen-nib"></i></div><h2>Your first story starts here</h2><p>Turn an idea into something worth reading. Your published stories will appear here.</p><a href="new_post.php" class="submit"><i class="fas fa-pen-nib"></i> Create your first story</a></div><?php endif;?></div></main><script src="../assets/interaction.js" defer></script><?php $statement->close();$con->close();?></body></html>
